// Turn a free-form Telegram message into the same ticket shape the
// classification logic expects. Telegram gives us raw chat text, not the
// structured {model, firmware_version, installer_type} fields a real
// installer app would send — those default to "not provided via chat" here.
// A production version would ask one follow-up question, or have the
// installer app tag the chat with equipment context (e.g. a QR scan at the
// unit) instead of relying on free text for that part.
const msg = $json.message;
const text = (msg && msg.text) || '';

// Pull out a known-style fault code if the installer happened to mention one:
// synthetic codes (E4, CONN-01) or real Vaillant-style codes (F.22, F22, F9998).
const codeMatch = text.match(/\b(E\d{1,2}|CONN-\d{2}|F\.?\d{2,4})\b/i);
let faultCode = '';
if (codeMatch) {
  let raw = codeMatch[1].toUpperCase();
  if (/^F\.?\d+$/.test(raw)) {
    // Normalize F22 / F.22 / F9998 all to the "F.NN" form the lookup table uses.
    raw = 'F.' + raw.replace(/^F\.?/, '');
  }
  faultCode = raw;
}

return {
  json: {
    chat_id: msg.chat.id,
    telegram_user: (msg.from && (msg.from.username || msg.from.first_name)) || 'unknown',
    model: 'not provided via chat',
    firmware_version: 'not provided via chat',
    installer_type: 'not provided via chat',
    fault_code: faultCode,
    reported_symptom: text
  }
};

// Deterministic fault-code lookup. Two sources feed this table:
// (1) the original 5 synthetic codes mirroring data/synthetic_fault_dataset.csv
// (2) real Vaillant aroTHERM fault codes, paraphrased from
//     data/manuals/fault_code_knowledge_base.json (see that file for sources/
//     copyright notes). Known codes skip the LLM entirely: fast, free, and
//     auditable. Unknown/blank codes (typically connectivity or
//     installer-error reports, which rarely carry a formal code) fall
//     through to manual-grounded LLM classification.
const KNOWN_CODES = {
  E4: {
    category: 'hardware_fault',
    fix_or_escalation_action: 'Escalate to hardware service technician (compressor/refrigerant circuit inspection). Not resolvable by app/firmware update.',
    source: 'synthetic fault dataset'
  },
  E7: {
    category: 'hardware_fault',
    fix_or_escalation_action: 'Escalate to hardware service technician (compressor/refrigerant circuit inspection). Not resolvable by app/firmware update.',
    source: 'synthetic fault dataset'
  },
  E12: {
    category: 'hardware_fault',
    fix_or_escalation_action: 'Escalate to hardware service technician (compressor/refrigerant circuit inspection). Not resolvable by app/firmware update.',
    source: 'synthetic fault dataset'
  },
  E2: {
    category: 'installer_error',
    fix_or_escalation_action: 'Correct commissioning step per install checklist (wiring, pressure fill, sensor orientation, or valve position); no manufacturer escalation needed.',
    source: 'synthetic fault dataset'
  },
  'CONN-01': {
    category: 'connectivity_issue',
    fix_or_escalation_action: 'Re-pair the control unit via the installer app, confirm router 2.4GHz band is enabled, and check smart-meter-gateway certificate status. No hardware visit required.',
    source: 'synthetic fault dataset'
  },
  // Real manufacturer fault codes — see data/manuals/fault_code_knowledge_base.json
  'F.22': {
    category: 'installer_error',
    fix_or_escalation_action: 'Check system water pressure at the filling loop; if below roughly 1 bar, top up to 1-1.5 bar. If pressure is already normal and the fault persists, escalate — likely a sensor fault.',
    source: 'Vaillant aroTHERM fault code reference'
  },
  'F.42': {
    category: 'hardware_fault',
    fix_or_escalation_action: 'Escalate to a certified technician — documented as a component-level fault inside the unit, not installer- or app-side.',
    source: 'Vaillant aroTHERM fault code reference'
  },
  'F.514': {
    category: 'hardware_fault',
    fix_or_escalation_action: 'Escalate to a certified technician — documented as a compressor inlet temperature sensor fault requiring internal inspection.',
    source: 'Vaillant aroTHERM fault code reference'
  },
  'F.532': {
    category: 'installer_error',
    fix_or_escalation_action: 'Check the building circuit for blockage, trapped air, or incorrect balancing before escalating — documented as usually an installation/flow issue, not a broken unit.',
    source: 'Vaillant aroTHERM fault code reference'
  },
  'F.718': {
    category: 'hardware_fault',
    fix_or_escalation_action: 'Escalate to a certified technician — documented as a blocked or faulty fan requiring hardware inspection.',
    source: 'Vaillant aroTHERM fault code reference'
  },
  'F.752': {
    category: 'installer_error',
    fix_or_escalation_action: 'Check incoming mains voltage, phase order, and earthing before escalating — documented as usually an electrical-supply issue at the installation, not a broken inverter.',
    source: 'Vaillant aroTHERM fault code reference'
  },
  'F.788': {
    category: 'installer_error',
    fix_or_escalation_action: 'Check the building circuit for air or restricted flow before escalating — documented as usually an installation-side pump/flow issue.',
    source: 'Vaillant aroTHERM fault code reference'
  },
  'F.9998': {
    category: 'installer_error',
    fix_or_escalation_action: 'Check eBUS wiring: correct cable type and polarity, no shielded/twisted cable, minimum clearance from power lines — documented as usually a wiring issue, not a broken controller.',
    source: 'Vaillant aroTHERM fault code reference'
  }
};

const item = $input.item.json;
const code = String(item.fault_code || '').trim().toUpperCase();
const match = KNOWN_CODES[code];

return {
  json: {
    ...item,
    matched: !!match,
    category: match ? match.category : null,
    fix_or_escalation_action: match ? match.fix_or_escalation_action : null,
    confidence: match ? 1 : null,
    source: match ? 'lookup' : null,
    manual_sources: match ? [match.source] : []
  }
};

// Parse the OpenAI Chat Completions response and recover the original
// ticket fields (the HTTP Request node's output replaces $json with
// OpenAI's response body, so the source ticket fields — including
// manual_context/manual_sources from the retrieval step — are pulled back
// from 'Retrieve Manual Context').
const original = $('Retrieve Manual Context').item.json;
const response = $input.item.json;

let parsed;
try {
  const text = response.choices[0].message.content;
  parsed = JSON.parse(text);
} catch (err) {
  // Fail safe: if the model output can't be parsed, escalate rather than
  // guess — never silently default to a "no action needed" outcome.
  parsed = {
    category: 'hardware_fault',
    fix_or_escalation_action: 'Could not parse model output — escalating to a senior technician as a safe default.',
    confidence: 0
  };
}

return {
  json: {
    ...original,
    category: parsed.category,
    fix_or_escalation_action: parsed.fix_or_escalation_action,
    confidence: parsed.confidence,
    source: 'llm'
  }
};

// Format the classification result as a short Telegram-friendly reply.
const item = $json;
const emoji = item.status === 'escalated' ? '\u{1F527}' : '\u2705'; // wrench vs check
const categoryLabel = {
  hardware_fault: 'Hardware fault',
  connectivity_issue: 'HEMS connectivity issue',
  installer_error: 'Installer/commissioning error'
}[item.category] || item.category;

const groundedInManual = !!(item.manual_sources && item.manual_sources.length > 0);
const sourceLabel = item.source === 'lookup'
  ? 'fault-code lookup'
  : (groundedInManual ? 'AI classification, grounded in manufacturer manual' : 'AI classification');

const lines = [
  emoji + ' *' + categoryLabel + '*',
  '',
  item.message,
  '',
  '_Source: ' + sourceLabel +
    (item.confidence != null && item.confidence !== '' ? ' (confidence ' + item.confidence + ')' : '') + '_'
];

return {
  json: {
    chat_id: item.chat_id,
    reply_text: lines.join('\n')
  }
};

// Round 1 grounding: lightweight keyword retrieval against a small manual
// knowledge base paraphrased from real Vaillant aroTHERM and Octopus Cosy
// documentation — see data/manuals/ for the source files, citations, and
// scope/limitations. Runs only when no known fault code resolved the
// ticket (i.e. the symptom is free text).
//
// This is deliberately lexical (keyword match), not embeddings-based —
// zero extra API calls, runs entirely inside this Code node. Upgrading to
// real multilingual embeddings + a vector store is explicit Round 2 scope
// (already budgeted in cost_estimation/cost_analysis.md). Keyword lists
// include a few German terms alongside English ones as a lightweight
// bridge for German-speaking installers — see workflow_documentation.md
// "Language" section for the fuller recommendation and where this
// approach's coverage runs out.
const MANUAL_KEYWORD_ENTRIES = [
  {
    id: 'wifi_hub_offline',
    category: 'connectivity_issue',
    keywords: ['wifi', 'wi-fi', 'router', 'network', 'verbindung', 'netzwerk', 'yellow light', 'gelbes licht', 'offline'],
    summary: 'A steady yellow hub light usually means lost WiFi, not a broken unit — check the router is powered on; the hub auto-reconnects once WiFi is back.',
    source: 'Octopus Cosy Hub/Pod status guide'
  },
  {
    id: 'primary_pod_disconnected',
    category: 'connectivity_issue',
    keywords: ['pod', 'sensor disconnected', 'primary sensor', 'room sensor', 'red light hub', 'sensor offline'],
    summary: 'A steady red hub light typically means the primary room sensor for a heating zone has dropped off — check its battery and proximity to the hub, or promote another sensor to primary.',
    source: 'Octopus Cosy Hub/Pod status guide'
  },
  {
    id: 'pod_low_battery',
    category: 'connectivity_issue',
    keywords: ['low battery', 'battery', 'flashing red sensor', 'aaa batteries', 'batterie'],
    summary: 'A slow-flashing red light on a room sensor is usually just a low battery, not a fault — replace with two fresh AAA batteries first.',
    source: 'Octopus Cosy Hub/Pod status guide'
  },
  {
    id: 'hub_fault_indicator',
    category: 'hardware_fault',
    keywords: ['flashing red hub', 'hub fault', 'unit fault indicator'],
    summary: 'A flashing red light on the hub itself (not a room sensor) is documented as an actual unit fault, not a connectivity problem — treat as hardware and escalate.',
    source: 'Octopus Cosy Hub/Pod status guide'
  },
  {
    id: 'ebus_comm_fault',
    category: 'installer_error',
    keywords: ['no communication', 'ebus', 'wiring fault', 'cable', 'polarity', 'controller not responding', 'kommunikationsfehler'],
    summary: 'Communication faults between the outdoor unit and its controller are documented as usually a wiring/cable-spec/polarity issue at installation, not a broken unit — check the eBUS wiring before escalating to the manufacturer.',
    source: 'Vaillant aroTHERM fault code reference (F.9998)'
  },
  {
    id: 'flow_rate_low',
    category: 'installer_error',
    keywords: ['no flow', 'low flow', 'pump not running', 'air in system', 'circulation', 'flow rate', 'wasserdurchfluss'],
    summary: 'Low or absent circulation flow is documented as usually a blockage, trapped air, or an incorrectly balanced circuit — an installer-side check, before it is treated as a hardware fault.',
    source: 'Vaillant aroTHERM fault code reference (F.532 / F.788)'
  },
  {
    id: 'evaporator_blocked',
    category: 'installer_error',
    keywords: ['blocked', 'debris', 'leaves', 'airflow restricted', 'frost buildup', 'ice on unit', 'evaporator dirty'],
    summary: 'Restricted airflow or excess frost on the outdoor unit is documented as typically caused by debris or a maintenance gap around the evaporator, not a component failure — clear and recheck before escalating.',
    source: 'Vaillant aroTHERM installation manual, §3.13–3.14'
  },
  {
    id: 'high_pressure_cutout',
    category: 'hardware_fault',
    keywords: ['high pressure', 'pressure switch', 'refrigerant leak', 'compressor cutting out', 'trips repeatedly'],
    summary: 'Refrigerant-circuit pressure exceeding the safety threshold trips a protective cutout after repeated failed restarts — documented as a hardware/refrigerant-circuit issue requiring a certified technician.',
    source: 'Vaillant aroTHERM installation manual, §3.14 (safety devices)'
  }
];

const item = $input.item.json;
const text = (item.reported_symptom || '').toLowerCase();

const scored = MANUAL_KEYWORD_ENTRIES
  .map(entry => ({
    entry,
    score: entry.keywords.filter(kw => text.includes(kw.toLowerCase())).length
  }))
  .filter(s => s.score > 0)
  .sort((a, b) => b.score - a.score)
  .slice(0, 2);

const manual_context = scored
  .map(s => '- ' + s.entry.summary + ' (Source: ' + s.entry.source + ')')
  .join('\n');

const manual_sources = scored.map(s => s.entry.source);

return {
  json: {
    ...item,
    manual_context: manual_context || null,
    manual_sources
  }
};
